async function buscarJson(url, { timeoutMs = 5000, signal } = {}) {
  const sinais = [AbortSignal.timeout(timeoutMs)];
  if (signal) sinais.push(signal);

  const resp = await fetch(url, { signal: AbortSignal.any(sinais) });
  if (!resp.ok) {
    const err = new Error('HTTP ' + resp.status);
    err.status = resp.status;
    throw err;
  }
  return resp.json();
}

