async function comRetry(fn, { tentativas = 3, baseMs = 200, tetoMs = 5000 } = {}) {
  for (let i = 0; ; i++) {
    try {
      return await fn();
    } catch (err) {
      const ultima = i >= tentativas - 1;
      if (ultima || !ehTransitorio(err)) throw err;
      const limite = Math.min(tetoMs, baseMs * 2 ** i);
      await esperar(Math.random() * limite);
    }
  }
}

async function mapComLimite(itens, limite, fn) {
  const resultados = new Array(itens.length);
  let proximo = 0;

  async function trabalhador() {
    while (proximo < itens.length) {
      const i = proximo++;
      resultados[i] = await fn(itens[i], i);
    }
  }

  const n = Math.min(limite, itens.length);
  await Promise.all(Array.from({ length: n }, trabalhador));
  return resultados;
}

