function balanceado(texto) {
  const pares = { ')': '(', ']': '[', '}': '{' };
  const pilha = [];
  for (const c of texto) {
    if (c === '(' || c === '[' || c === '{') pilha.push(c);
    else if (c in pares) {
      if (pilha.pop() !== pares[c]) return false;
    }
  }
  return pilha.length === 0;
}

