function primeiraOcorrencia(ordenado, alvo) {
  let esq = 0;
  let dir = ordenado.length - 1;
  let resposta = -1;
  while (esq <= dir) {
    const meio = Math.floor((esq + dir) / 2);
    if (ordenado[meio] === alvo) {
      resposta = meio;
      dir = meio - 1;
    } else if (ordenado[meio] < alvo) {
      esq = meio + 1;
    } else {
      dir = meio - 1;
    }
  }
  return resposta;
}

