function primeiroRuim(n, bom) {
  let lo = 0, hi = n - 1; // assume bom(lo) === true e bom(hi) === false
  let testes = 0;
  while (hi - lo > 1) {
    const meio = Math.floor((lo + hi) / 2);
    testes++;
    if (bom(meio)) lo = meio; else hi = meio;
  }
  return { indice: hi, testes };
}

