lab.solution:
function planejarEntregas(ruas, pedidos, deposito) {
  const grafo = new Map();
  const ligar = (a, b) => { if (!grafo.has(a)) grafo.set(a, []); grafo.get(a).push(b); };
  for (const [a, b] of ruas) { ligar(a, b); ligar(b, a); }
  const dist = new Map([[deposito, 0]]);
  const fila = [deposito];
  for (let i = 0; i < fila.length; i++) {
    const v = fila[i];
    for (const w of grafo.get(v) || []) if (!dist.has(w)) { dist.set(w, dist.get(v) + 1); fila.push(w); }
  }
  const alcancaveis = [];
  const inalcancaveis = [];
  const porBairro = new Map();
  for (const p of pedidos) {
    if (!dist.has(p.bairro)) { inalcancaveis.push(p); continue; }
    alcancaveis.push({ ...p, distancia: dist.get(p.bairro) });
    porBairro.set(p.bairro, (porBairro.get(p.bairro) || 0) + 1);
  }
  alcancaveis.sort((a, b) => a.prioridade - b.prioridade || a.distancia - b.distancia || a.id - b.id);
  return { fila: alcancaveis, inalcancaveis, porBairro };
}

