function criarDebounce(fn, ms) {
  let t = null;
  function debounced(...args) {
    clearTimeout(t);
    t = setTimeout(() => { t = null; fn(...args); }, ms);
  }
  debounced.cancel = () => { clearTimeout(t); t = null; };
  return debounced;
}

