function verificarAcessibilidade(elementos) {
  const vazio = (v) => v === undefined || v === null || String(v).trim() === '';
  const temNome = (a) => !vazio(a['aria-label']) || !vazio(a['aria-labelledby']) || !vazio(a.title);
  const paraIds = new Set(elementos.filter((e) => e.tag === 'label' && e.attrs && !vazio(e.attrs.for)).map((e) => e.attrs.for));
  const out = [];
  elementos.forEach((e, indice) => {
    const a = e.attrs || {};
    if (e.tag === 'button' && vazio(e.texto) && !temNome(a)) out.push({ indice, regra: 'button-name' });
    if (e.tag === 'img' && !('alt' in a) && a.role !== 'presentation' && a.role !== 'none') out.push({ indice, regra: 'image-alt' });
    if (e.tag === 'input') {
      const tipo = a.type || 'text';
      if (!['hidden', 'submit', 'button', 'reset', 'image'].includes(tipo) && !temNome(a) && !(!vazio(a.id) && paraIds.has(a.id))) out.push({ indice, regra: 'label' });
    }
  });
  return out;
}

