items.solution:
function resolverExports(mapa, caminho, condicoes = ['import', 'default']) {
  const erro = () => new Error('ERR_PACKAGE_PATH_NOT_EXPORTED: ' + caminho);
  let subs;
  if (typeof mapa === 'string') subs = { '.': mapa };
  else if (mapa && Object.keys(mapa).some((k) => k.startsWith('.'))) subs = mapa;
  else subs = { '.': mapa };
  const destino = (v, coringa) => {
    if (typeof v === 'string') return coringa === undefined ? v : v.replace('*', coringa);
    if (v && typeof v === 'object') {
      for (const k of Object.keys(v)) if (condicoes.includes(k)) { const r = destino(v[k], coringa); if (r !== undefined) return r; }
    }
    return undefined;
  };
  let valor, coringa;
  if (Object.hasOwn(subs, caminho)) valor = subs[caminho];
  else {
    for (const chave of Object.keys(subs)) {
      const i = chave.indexOf('*');
      if (i < 0) continue;
      const pre = chave.slice(0, i), pos = chave.slice(i + 1);
      if (caminho.length >= chave.length - 1 && caminho.startsWith(pre) && caminho.endsWith(pos)) { valor = subs[chave]; coringa = caminho.slice(pre.length, caminho.length - pos.length); break; }
    }
  }
  if (valor === undefined || valor === null) throw erro();
  const r = destino(valor, coringa);
  if (r === undefined) throw erro();
  return r;
}

