function combinacoes(variantes, opcoes = {}) {
  const chaves = Object.keys(variantes);
  const total = chaves.reduce((n, k) => n * variantes[k].length, 1);
  if (opcoes.max !== undefined && total > opcoes.max) throw new Error('combinações demais: ' + total);
  let lista = [{}];
  for (const k of chaves) lista = lista.flatMap((base) => variantes[k].map((v) => ({ ...base, [k]: v })));
  return opcoes.excluir ? lista.filter((c) => !opcoes.excluir(c)) : lista;
}

