items.solution:
function podeRemover(depreciadoEm, versaoAlvo, publicadas, minimoLancamentos) {
  const analisar = (v) => {
    const m = /^(\d+)\.(\d+)\.(\d+)$/.exec(v);
    if (!m) throw new Error('versão inválida: ' + v);
    return [+m[1], +m[2], +m[3]];
  };
  const cmp = (a, b) => { for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] - b[i]; return 0; };
  const d = analisar(depreciadoEm), alvo = analisar(versaoAlvo);
  const pubs = publicadas.map(analisar);
  if (alvo[0] <= d[0]) return false;
  const lancamentos = pubs.filter((v) => cmp(v, d) > 0 && cmp(v, alvo) < 0 && v[2] === 0);
  return lancamentos.length >= minimoLancamentos;
}

