items.solution:
function classificarMudanca(antes, depois) {
  const niveis = ['nenhuma', 'patch', 'minor', 'major'];
  let nivel = 0;
  const marca = (n) => { nivel = Math.max(nivel, niveis.indexOf(n)); };
  const a = antes.props || {}, d = depois.props || {};
  for (const nome of Object.keys(a)) {
    if (!(nome in d)) { marca('major'); continue; }
    const x = a[nome], y = d[nome];
    if (x.tipo !== y.tipo) marca('major');
    if (!x.obrigatoria && y.obrigatoria) marca('major');
    if (x.obrigatoria && !y.obrigatoria) marca('minor');
    const ox = x.opcoes || [], oy = y.opcoes || [];
    if (ox.some((o) => !oy.includes(o))) marca('major');
    if (oy.some((o) => !ox.includes(o))) marca('minor');
    if (x.descricao !== y.descricao) marca('patch');
  }
  for (const nome of Object.keys(d)) if (!(nome in a)) marca(d[nome].obrigatoria ? 'major' : 'minor');
  return niveis[nivel];
}

