function criarEstadoControlavel(opcoes) {
  let { value, defaultValue, onChange } = opcoes;
  let interno = defaultValue;
  const controlado = () => value !== undefined;
  return {
    obter: () => (controlado() ? value : interno),
    definir(v) {
      if (!controlado()) interno = v;
      if (onChange) onChange(v);
    },
    atualizarProps(novas) {
      const eraControlado = controlado();
      const novoValue = 'value' in novas ? novas.value : value;
      if (eraControlado !== (novoValue !== undefined)) throw new Error('troca de modo controlado/não controlado');
      value = novoValue;
      if ('onChange' in novas) onChange = novas.onChange;
    }
  };
}

