function mesclarProps(propsDoComponente, propsDoUsuario) {
  const out = {};
  const chaves = new Set([...Object.keys(propsDoComponente), ...Object.keys(propsDoUsuario)]);
  for (const k of chaves) {
    const noC = k in propsDoComponente, noU = k in propsDoUsuario;
    const c = propsDoComponente[k], u = propsDoUsuario[k];
    if (!(noC && noU)) { out[k] = noU ? u : c; continue; }
    if (/^on[A-Z]/.test(k) && typeof c === 'function' && typeof u === 'function') {
      out[k] = (evento, ...resto) => { u(evento, ...resto); if (!(evento && evento.defaultPrevented)) c(evento, ...resto); };
    } else if (k === 'className') out[k] = [c, u].filter(Boolean).join(' ');
    else if (k === 'style') out[k] = { ...c, ...u };
    else out[k] = u;
  }
  return out;
}

