function calcularTempos(arvore, modo) {
  if (modo !== 'cascata' && modo !== 'paralelo') throw new Error('modo inválido: ' + modo);
  const inicios = {}, fins = {};
  (function visitar(n, inicioPai) {
    const ini = modo === 'cascata' ? inicioPai : 0;
    inicios[n.id] = ini; fins[n.id] = ini + n.ms;
    (n.filhos || []).forEach((f) => visitar(f, fins[n.id]));
  })(arvore, 0);
  return { inicios, fins, total: Math.max(...Object.values(fins)) };
}

