function criarCachePromises(buscar) {
  const cache = new Map();
  let total = 0;
  return {
    obter(chave) {
      if (cache.has(chave)) return cache.get(chave);
      total++;
      const p = Promise.resolve().then(() => buscar(chave));
      cache.set(chave, p);
      p.catch(() => { if (cache.get(chave) === p) cache.delete(chave); });
      return p;
    },
    invalidar(chave) { cache.delete(chave); },
    chamadas: () => total
  };
}

