function simularAgendador(atualizacoes) {
  const restante = {};
  atualizacoes.forEach((a) => { restante[a.id] = a.custo; });
  const conclusao = {}, ordem = [];
  let pendentes = atualizacoes.length;
  const prio = (t) => (t === 'urgente' ? 0 : 1);
  let t = 0;
  while (pendentes > 0) {
    const prontos = atualizacoes.map((a, i) => ({ a, i })).filter(({ a }) => a.chegada <= t && restante[a.id] > 0);
    if (!prontos.length) { t++; continue; }
    prontos.sort((x, y) => prio(x.a.tipo) - prio(y.a.tipo) || x.a.chegada - y.a.chegada || x.i - y.i);
    const { a } = prontos[0];
    restante[a.id]--; t++;
    if (restante[a.id] === 0) { conclusao[a.id] = t; ordem.push(a.id); pendentes--; }
  }
  return { conclusao, ordem };
}

