function calcularCLS(mudancas) {
  const lista = mudancas.filter((m) => !m.entradaRecente).sort((a, b) => a.instante - b.instante);
  let melhor = 0, soma = 0, inicio = 0, ultimo = 0, aberta = false;
  for (const m of lista) {
    if (!aberta || m.instante - ultimo > 1000 || m.instante - inicio >= 5000) { soma = 0; inicio = m.instante; aberta = true; }
    soma += m.valor; ultimo = m.instante;
    if (soma > melhor) melhor = soma;
  }
  return Math.round(melhor * 1000) / 1000;
}

