function calcularTBT(tarefas, fcp, tti) {
  if (tti < fcp) throw new Error('janela inválida');
  let total = 0;
  for (const t of tarefas) {
    const efetiva = Math.min(t.fim, tti) - Math.max(t.inicio, fcp);
    if (efetiva > 50) total += efetiva - 50;
  }
  return total;
}

