items.solution:
function memoizarLimitado(fn, max) {
  if (!(max >= 1)) throw new Error('limite inválido');
  const cache = new Map();
  let n = 0;
  const f = (chave) => {
    if (cache.has(chave)) { const v = cache.get(chave); cache.delete(chave); cache.set(chave, v); return v; }
    n++;
    const v = fn(chave);
    cache.set(chave, v);
    if (cache.size > max) cache.delete(cache.keys().next().value);
    return v;
  };
  f.chamadas = () => n;
  f.tamanho = () => cache.size;
  return f;
}

