items.solution:
function verificarOrcamento(medidas, orcamento, opcoes = {}) {
  const margem = opcoes.margem || 0;
  const violacoes = [];
  for (const chave of Object.keys(orcamento).sort()) {
    const { max, nivel = 'error' } = orcamento[chave];
    const limite = max * (1 + margem / 100);
    if (!(chave in medidas)) { violacoes.push({ chave, valor: null, limite, nivel: 'error', tipo: 'sem medida' }); continue; }
    if (medidas[chave] > limite) violacoes.push({ chave, valor: medidas[chave], limite, nivel, tipo: 'acima do limite' });
  }
  return { ok: !violacoes.some((v) => v.nivel === 'error'), violacoes };
}

