  window.dispatchEvent(new CustomEvent('carrinho:item-adicionado', { detail: { versao: 2, itemId, quantidade } }));
}

// consumidor (Cabeçalho)
function useSeloDoCarrinho() {
  const [itens, setItens] = useState(0);
