function somarComDuplicacao(pedidos, itens, campo) {
  let linhas = 0, errada = 0, correta = 0;
  for (const p of pedidos) {
    const n = itens.filter((i) => i.pedidoId === p.id).length;
    const v = p[campo] || 0;
    linhas += n;
    errada += v * n;
    if (n > 0) correta += v;
  }
  return { linhasDoJoin: linhas, errada, correta };
}

