function colunasUsaveis(indice, condicoes) {
  let n = 0;
  for (const col of indice) {
    const c = condicoes.find((x) => x.coluna === col);
    if (!c) break;
    n++;
    if (c.op !== '=') break;
  }
  return n;
}

