const esq = Array.from({ length: 100 }, (_, i) => ({ a: i }));
const dir = Array.from({ length: 200 }, (_, i) => ({ a: i % 100, v: i }));
const n = nestedLoop(esq, dir, 'a', 'a');
const h = hashJoin(esq, dir, 'a', 'a');
assert.equal(n.comparacoes, 20000);
