items.solution:
function verificarTotais(pedidos, itens) {
  const arred = (x) => Math.round(x * 100) / 100;
  const soma = new Map();
  for (const i of itens) soma.set(i.pedidoId, (soma.get(i.pedidoId) || 0) + i.valor);
  const out = [];
  for (const p of pedidos) {
    const real = arred(soma.get(p.id) || 0);
    const guardado = arred(p.totalGuardado);
    if (real !== guardado) out.push({ id: p.id, guardado, real, diferenca: arred(real - guardado) });
  }
  return out;
}

