function escolherChave(req) {
  if (req.distribuida && req.volumeAlto) return 'uuid-ordenado';
  if (req.distribuida) return 'uuid';
  if (req.expostaPublicamente) return 'bigint+id-publico';
  return 'bigint';
}
function backfillEmLotes(minId, maxId, tamanho) {
  if (tamanho < 1 || minId > maxId) throw new Error('parâmetros inválidos');
  const faixas = [];
  for (let de = minId; de <= maxId; de += tamanho) faixas.push({ de, ate: Math.min(de + tamanho - 1, maxId) });
  return faixas;
}

