function podeInserirConta(contas, email) {
  return !contas.some((c) => c.email === email && c.removidoEm === null);
}
function caminhoAteRaiz(nos, id) {
  const porId = new Map(nos.map((n) => [n.id, n]));
  const caminho = [];
  const visto = new Set();
  let atual = id;
  while (atual !== null) {
    if (visto.has(atual)) throw new Error('ciclo detectado');
    const n = porId.get(atual);
    if (!n) throw new Error('nó inexistente: ' + atual);
    visto.add(atual);
    caminho.push(atual);
    atual = n.pai;
  }
  return caminho;
}

