const docs = [{ n: 'a', v: 5, s: 'x' }, { n: 'b', v: 15, s: 'y' }, { n: 'c', v: 25, s: 'z' }];
assert.equal(JSON.stringify(filtrar(docs, { s: { $in: ['x', 'z'] }, v: { $ne: 5 } }).map(d => d.n)), '["c"]');
