items.solution:
function filtrar(docs, filtro) {
  const ok = (valor, cond) => {
    if (cond !== null && typeof cond === 'object') {
      return Object.entries(cond).every(([op, x]) => {
        if (op === '$gt') return valor > x;
        if (op === '$gte') return valor >= x;
        if (op === '$lt') return valor < x;
        if (op === '$lte') return valor <= x;
        if (op === '$ne') return valor !== x;
        if (op === '$in') return x.includes(valor);
        throw new Error('operador desconhecido: ' + op);
      });
    }
    return valor === cond;
  };
  return docs.filter((d) => Object.entries(filtro).every(([campo, cond]) => ok(d[campo], cond)));
}

