function agruparPor(docs, chave, campo) {
  const m = new Map();
  for (const d of docs) {
    const g = m.get(d[chave]) || { _id: d[chave], n: 0, total: 0 };
    g.n += 1;
    g.total += d[campo];
    m.set(d[chave], g);
  }
  return [...m.values()].sort((a, b) => (a._id < b._id ? -1 : a._id > b._id ? 1 : 0));
}

