items.solution:
function abrirVaga(chaves, max, politica) {
  if (politica === 'noeviction') return { ok: !(chaves.length >= max), removidas: [] };
  const ordenadas = [...chaves].sort((a, b) => a.ultimoAcesso - b.ultimoAcesso);
  const qtd = Math.max(0, chaves.length - (max - 1));
  return { ok: true, removidas: ordenadas.slice(0, qtd).map((x) => x.k) };
}

