function chaveCache(prefixo, versao, tenant, params = {}) {
  const partes = [prefixo, 'v' + versao, tenant];
  const ks = Object.keys(params).sort();
  if (ks.length) partes.push(ks.map((k) => k + '=' + params[k]).join('&'));
  return partes.join(':');
}

