function descarregar(fila) {
  const ultimo = new Map();
  for (const [id, preco] of fila) ultimo.set(id, preco);
  const itens = [...ultimo.entries()].sort((a, b) => a[0] - b[0]).map(([id, preco]) => [id, preco]);
  return { itens, coalescidas: fila.length - ultimo.size };
}

