items.solution:
function criarLRU(cap) {
  const m = new Map();
  return {
    get(k) {
      if (!m.has(k)) return undefined;
      const v = m.get(k); m.delete(k); m.set(k, v); return v;
    },
    set(k, v) {
      if (m.has(k)) m.delete(k);
      m.set(k, v);
      if (m.size > cap) m.delete(m.keys().next().value);
    },
    chaves() { return [...m.keys()]; }
  };
}

