items.solution:
function hashTag(chave) {
  const i = chave.indexOf('{');
  if (i === -1) return chave;
  const j = chave.indexOf('}', i + 1);
  if (j === -1 || j === i + 1) return chave;
  return chave.slice(i + 1, j);
}

