function executar(mws, req) {
  const ordem = []; let erro = null;
  const passo = (i) => {
    if (i >= mws.length) return;
    ordem.push(i);
    mws[i](req, (err) => { if (err) { erro = err; return; } passo(i + 1); });
  };
  passo(0);
  return { ordem, erro };
}

