function podeInjetar(modulos, consumidor, token) {
  const m = modulos[consumidor] || {};
  if ((m.providers || []).includes(token)) return true;
  return (m.imports || []).some((nome) => ((modulos[nome] || {}).exports || []).includes(token));
}

