items.solution:
function tickHeartbeat(clientes) {
  const encerrar = [], pingar = [], proximo = [];
  for (const c of clientes) {
    if (!c.vivo) { encerrar.push(c.id); continue; }
    pingar.push(c.id); proximo.push({ id: c.id, vivo: false });
  }
  return { encerrar, pingar, proximo };
}

