items.solution:
function calcularBackoff(tipo, base, tentativas, rnd) {
  return Array.from({ length: Math.max(0, tentativas - 1) }, (_, i) => {
    const b = base * 2 ** i;
    if (tipo === 'fixed') return base;
    if (tipo === 'exponential') return b;
    return Math.round(b / 2 + rnd() * b / 2);
  });
}

