items.solution:
function estimarPercentil(limites, cumulativos, total, q) {
  const alvo = q * total;
  const i = cumulativos.findIndex((c) => c >= alvo);
  const inf = i === 0 ? 0 : limites[i - 1], ant = i === 0 ? 0 : cumulativos[i - 1];
  return inf + (limites[i] - inf) * ((alvo - ant) / (cumulativos[i] - ant));
}

