function taxa(amostras) {
  if (amostras.length < 2) return 0;
  let inc = 0;
  for (let i = 1; i < amostras.length; i++) {
    const a = amostras[i - 1][1], b = amostras[i][1];
    inc += b >= a ? b - a : b;
  }
  return inc / (amostras[amostras.length - 1][0] - amostras[0][0]);
}

