items.solution:
function inconsistencias(pedidos, reservas, cobrancas) {
  const r = { confirmadosSemReserva: 0, confirmadosSemCobranca: 0, canceladosComReserva: 0, canceladosCobrados: 0 };
  for (const [id, st] of Object.entries(pedidos)) {
    if (st === 'CONFIRMADO') { if (!reservas.has(id)) r.confirmadosSemReserva++; if (!cobrancas.has(id)) r.confirmadosSemCobranca++; }
    else { if (reservas.has(id)) r.canceladosComReserva++; if (cobrancas.has(id)) r.canceladosCobrados++; }
  }
  return r;
}

