function ejecaoEm(statuses, consecutivos) {
  let seguidos = 0;
  for (let i = 0; i < statuses.length; i++) {
    if (statuses[i] >= 500 && statuses[i] <= 599) { seguidos++; if (seguidos >= consecutivos) return i; } else seguidos = 0;
  }
  return -1;
}

